const body = $input.first().json.body;

const validBrands = ['cloveh2o', 'mindwave', 'sentaient'];
const validInputTypes = ['url', 'text', 'pdf'];
const validCampaignTypes = ['viral_hook', 'technical_deep_dive', 'founder_story'];
const validFormats = ['9:16', '1:1', '16:9', 'email'];

// Validate required fields
if (!body.brand || !validBrands.includes(body.brand)) {
  throw new Error(`Invalid brand. Must be one of: ${validBrands.join(', ')}`);
}
if (!body.input_type || !validInputTypes.includes(body.input_type)) {
  throw new Error(`Invalid input_type. Must be one of: ${validInputTypes.join(', ')}`);
}
if (!body.input_value) {
  throw new Error('input_value is required');
}

const campaignType = body.campaign_type || 'viral_hook';
const formats = body.requested_formats || ['9:16', '1:1'];
const campaignId = `campaign_${body.brand}_${Date.now()}`;

return [{
  json: {
    campaign_id: campaignId,
    brand: body.brand,
    input_type: body.input_type,
    input_value: body.input_value,
    campaign_type: campaignType,
    requested_formats: formats,
    status: 'validated',
    created_at: new Date().toISOString()
  }
}];

const campaign = $('validate_input').first().json;
const rawFile = $('load_brand_codes').first().json.data;
const allCodes = JSON.parse(rawFile);

const brandConfig = allCodes.brands[campaign.brand];
const templateConfig = allCodes.campaign_templates[campaign.campaign_type];
const orchestratorConfig = allCodes.orchestrator_config;

if (!brandConfig) {
  throw new Error(`Brand config not found for: ${campaign.brand}`);
}

return [{
  json: {
    ...campaign,
    brand_config: brandConfig,
    template_config: templateConfig,
    orchestrator_config: orchestratorConfig,
    status: 'context_loaded'
  }
}];

