const data = $input.first().json;
let strategy;

try {
  strategy = JSON.parse(data.text || data.content?.[0]?.text || '{}');
} catch(e) {
  throw new Error('Failed to parse strategy JSON from LLM: ' + e.message);
}

const confidence = parseFloat(strategy.CONFIDENCE_SCORE || strategy.confidence_score || 0);
const threshold = 0.90;

return [{
  json: {
    ...data,
    strategy,
    confidence,
    passes_threshold: confidence >= threshold,
    status: confidence >= threshold ? 'approved' : 'needs_human_review'
  }
}];

const data = $input.first().json;
const stagingPath = `/marketing/media/staging/${data.campaign_id}`;

const metadata = {
  campaign_id: data.campaign_id,
  brand: data.brand,
  campaign_type: data.campaign_type,
  confidence: data.confidence,
  strategy: data.strategy,
  requested_formats: data.requested_formats,
  status: 'staged',
  staged_at: new Date().toISOString(),
  paths: {
    staging: stagingPath,
    script: `${stagingPath}/script.txt`,
    caption: `${stagingPath}/caption.txt`,
    visual_brief: `${stagingPath}/visual_brief.txt`,
    approved: `/marketing/media/approved/${data.campaign_id}`
  }
};

return [{ json: metadata }];
